<script setup lang="ts">
import{onMounted,reactive,ref}from'vue'
import { actualizarPersona, detallePersona, listarPersonas } from '../services/personas'
import type { CambioPersona, Persona, PersonaPayload } from '../interfaces/personas.interface'

const rows=ref<Persona[]>([]),criterion=ref(''),page=ref(1),last=ref(1),total=ref(0),loading=ref(false),saving=ref(false),selected=ref<Persona|null>(null),logs=ref<CambioPersona[]>([]),logPage=ref(1),logLast=ref(1),error=ref(''),success=ref('')
const form=reactive<PersonaPayload>({apellido_paterno:'',apellido_materno:'',nombre:'',dni:'',telefono_fijo:'',celular:'',email:''})
async function load(target=1){page.value=target;loading.value=true;error.value='';try{const result=await listarPersonas(criterion.value,target);rows.value=result.data;total.value=result.total;last.value=result.last_page}catch(e){error.value=message(e)}finally{loading.value=false}}
async function open(row:Persona,targetLog=1){error.value='';try{const result=await detallePersona(row.id,targetLog);selected.value=result.persona;Object.assign(form,{apellido_paterno:result.persona.apellido_paterno,apellido_materno:result.persona.apellido_materno,nombre:result.persona.nombre,dni:result.persona.dni,telefono_fijo:result.persona.telefono_fijo||'',celular:result.persona.celular||'',email:result.persona.email||''});logs.value=result.logs.data;logPage.value=result.logs.current_page;logLast.value=result.logs.last_page}catch(e){error.value=message(e)}}
function validate(){if(form.apellido_paterno.trim().length<2||form.apellido_materno.trim().length<2||form.nombre.trim().length<2)return'Los nombres y apellidos deben contener al menos 2 caracteres.';if(!/^\d{8}$/.test(form.dni))return'El DNI debe contener exactamente 8 dígitos.';if(form.celular&&!/^\d{9}$/.test(form.celular))return'El celular debe contener exactamente 9 dígitos.';if(form.telefono_fijo&&!/^\d+$/.test(form.telefono_fijo))return'El teléfono fijo solo admite números.';if(form.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email))return'Ingrese un correo electrónico válido.';return''}
async function save(){if(!selected.value)return;const issue=validate();if(issue){error.value=issue;return}saving.value=true;error.value='';try{const updated=await actualizarPersona(selected.value.id,{...form});success.value='Los datos de la persona se actualizaron correctamente.';await open(updated);await load(page.value)}catch(e){error.value=message(e)}finally{saving.value=false}}
function fullName(row:Persona){return row.nombre_completo||`${row.apellido_paterno} ${row.apellido_materno}, ${row.nombre}`}
function message(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}
onMounted(()=>load())
</script>

<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Sistema / Personas</nav><header class="hero"><div class="mark">PE</div><div><small>ADMINISTRACIÓN GENERAL</small><h1>Gestión de personas</h1><p>Datos personales, información de contacto e historial de cambios.</p></div><strong>{{total}} personas</strong></header><div v-if="success" class="flash good">✓ {{success}}</div><div v-if="error" class="flash bad">{{error}}</div><section class="search"><label>Buscar por DNI o nombre<input v-model.trim="criterion" placeholder="Ingrese al menos un criterio" @keyup.enter="load()"></label><button @click="load()">Buscar</button><button class="clear" @click="criterion='';load()">Limpiar</button></section><div v-if="loading" class="empty">Consultando personas…</div><div v-else-if="!rows.length" class="empty">No se encontraron personas.</div><section v-else class="table"><header><span>Persona</span><span>DNI</span><span>Contacto</span><span>Acción</span></header><article v-for="row in rows" :key="row.id"><div><b>{{fullName(row)}}</b><small>Registro #{{row.id}}</small></div><code>{{row.dni}}</code><div><b>{{row.celular||row.telefono_fijo||'Sin teléfono'}}</b><small>{{row.email||'Sin correo electrónico'}}</small></div><button @click="open(row)">Modificar datos</button></article></section><footer v-if="last>1" class="pages"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{last}}</span><button :disabled="page>=last" @click="load(page+1)">Siguiente</button></footer><div v-if="selected" class="backdrop" @mousedown.self="selected=null"><section class="modal"><header><div><small>PERSONA #{{selected.id}}</small><h2>{{fullName(selected)}}</h2></div><button @click="selected=null">×</button></header><div class="content"><form @submit.prevent="save"><h3>Información personal</h3><div class="grid"><label>Apellido paterno *<input v-model.trim="form.apellido_paterno"></label><label>Apellido materno *<input v-model.trim="form.apellido_materno"></label><label>Nombres *<input v-model.trim="form.nombre"></label><label>DNI *<input v-model.trim="form.dni" maxlength="8" inputmode="numeric"></label><label>Teléfono fijo<input v-model.trim="form.telefono_fijo" inputmode="numeric"></label><label>Celular<input v-model.trim="form.celular" maxlength="9" inputmode="numeric"></label><label class="wide">Correo electrónico<input v-model.trim="form.email" type="email"></label></div><footer><button type="button" class="clear" @click="selected=null">Cancelar</button><button :disabled="saving">{{saving?'Actualizando…':'Actualizar persona'}}</button></footer></form><aside><h3>Historial de cambios</h3><div v-if="!logs.length" class="no-logs">No existen cambios registrados.</div><article v-for="log in logs" :key="log.id"><header><b>Cambio de datos</b><time>{{log.created_at}}</time></header><p>{{log.apellido_paterno}} {{log.apellido_materno}}, {{log.nombre}}</p><dl><div><dt>DNI</dt><dd>{{log.dni}}</dd></div><div><dt>Celular</dt><dd>{{log.celular||'—'}}</dd></div><div><dt>Correo</dt><dd>{{log.email||'—'}}</dd></div></dl><small>{{log.usuario||'Usuario del sistema'}}<template v-if="log.empresa"> · {{log.empresa}}</template></small></article><footer v-if="logLast>1"><button :disabled="logPage<=1" @click="open(selected!,logPage-1)">Anterior</button><span>{{logPage}} / {{logLast}}</span><button :disabled="logPage>=logLast" @click="open(selected!,logPage+1)">Siguiente</button></footer></aside></div></section></div></div></template>

<style scoped>
.page{--a:#334a61;color:#35444c}nav{margin-bottom:16px;color:#96a0a5;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-weight:800}.hero small,.modal small{color:var(--a);font-size:.52rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.28rem}.hero p{margin:0;color:#7c898f;font-size:.62rem}.hero strong{margin-left:auto;font-size:.5rem}.flash{padding:10px;font-size:.6rem}.good{color:#267359;background:#eaf8f1}.bad{color:#a13e43;background:#fff0f0}.search{margin-top:12px;padding:12px;display:grid;grid-template-columns:1fr auto auto;align-items:end;gap:8px;background:#fff}.search label,.modal label{font-size:.47rem}input{width:100%;padding:8px;border:1px solid #d7e0e3;border-radius:5px;font:inherit;font-size:.52rem}.search button,.pages button,.table article>button,.modal form footer button,.modal aside footer button{padding:8px 10px;border:0;border-radius:5px;color:#fff;background:var(--a);font-size:.47rem}.clear{color:#68767c!important;background:#edf1f2!important}.table{margin-top:12px;background:#fff}.table>header,.table>article{padding:10px 12px;display:grid;grid-template-columns:1.5fr .6fr 1.2fr .65fr;align-items:center;gap:9px;border-bottom:1px solid #e9edee}.table>header{color:#849096;background:#f4f6f7;font-size:.42rem}.table article{font-size:.47rem}.table b,.table small{display:block}.table small{color:#89949a;font-size:.4rem}.table code{color:#31566e}.empty{margin-top:12px;padding:45px;text-align:center;background:#fff;font-size:.58rem}.pages{display:flex;justify-content:center;align-items:center;gap:10px;font-size:.48rem}.backdrop{position:fixed;z-index:100;inset:0;padding:16px;display:grid;place-items:center;background:#14283888}.modal{width:min(1000px,100%);max-height:94vh;overflow:auto;border-radius:12px;background:#fff}.modal>header{padding:18px 20px;display:flex;border-bottom:1px solid #e4e9eb}.modal h2{margin:2px 0;font-size:.9rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.content{display:grid;grid-template-columns:1.1fr .9fr}.content>form,.content>aside{padding:20px}.content>aside{border-left:1px solid #e4e9eb;background:#fafbfb}.modal h3{margin:0 0 12px;font-size:.62rem}.grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}.wide{grid-column:span 2}.modal form footer{margin-top:15px;display:flex;justify-content:flex-end;gap:5px}.modal aside>article{margin-bottom:8px;padding:10px;border:1px solid #e2e7e9;border-radius:6px;background:#fff;font-size:.44rem}.modal aside article header{display:flex}.modal time{margin-left:auto;color:#89949a}.modal aside p{margin:5px 0}.modal dl{margin:0}.modal dl div{display:flex}.modal dt{color:#89949a}.modal dd{margin-left:auto}.modal aside article>small{display:block;margin-top:6px;color:#66777f}.modal aside>footer{display:flex;justify-content:center;align-items:center;gap:7px;font-size:.43rem}.no-logs{padding:25px;text-align:center;font-size:.48rem}@media(max-width:750px){.table>header{display:none}.table>article,.content{grid-template-columns:1fr}.content>aside{border-top:1px solid #e4e9eb;border-left:0}}@media(max-width:520px){.hero{flex-wrap:wrap}.hero strong{margin-left:0}.search,.grid{grid-template-columns:1fr}.wide{grid-column:auto}}
</style>
